/** Volume drawn by each boat on days from `fromDay` up to but not including `toDay`, largest first, ties by name. The yard's own draws are left out. */
export function usageByBoat(ledger: Ledger, fromDay: number, toDay: number): Array<[string, number]> {
    const totals = new Map<string, number>();
    for (const entry of ledger.entries) {
        if (entry.kind !== "draw" || entry.boat === YARD) {
            continue;
        }
        if (entry.day < fromDay || entry.day >= toDay) {
            continue;
        }
        totals.set(entry.boat, (totals.get(entry.boat) ?? 0) + entry.volume);
    }
    return Array.from(totals.entries()).sort((a, b) => {
        if (b[1] !== a[1]) {
            return b[1] - a[1];
        }
        return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
    });
}
